var n=new URL("api/v1/",document.baseURI);async function s(e){let t=await fetch(new URL(e,n));if(!t.ok)throw new Error(`${e}: ${t.status} ${(await t.json()).message}`);return await t.json()}var r={state:()=>s("state"),events:e=>s(`events?since=${e}`),lane:(e,t=0)=>s(`lane/${encodeURIComponent(e)}?before=${t}`),async post(e,t){return await(await fetch(new URL(e,n),{method:"POST",body:new URLSearchParams(t)})).json()}};export{r as api};
